import { format, resolveConfig } from 'prettier';
import { readFile, writeFile } from 'node:fs/promises';
import { designTokenCss, responsiveTokenCss } from '../../web/src/shared/ui/tokens';
import {
  offlineCopy,
  publicDocument,
  publicSurfaceCss,
} from '../../web/src/shared/ui/public-document';

const outputs = [
  {
    path: 'web/src/shared/ui/tokens.css',
    parser: 'css',
    source:
      '/* Generated by backend/scripts/design-tokens.ts. Edit tokens.ts. */\n' +
      designTokenCss(':root, .store') +
      responsiveTokenCss,
  },
  {
    path: 'web/src/shared/ui/public.css',
    parser: 'css',
    source:
      "/* Generated by backend/scripts/design-tokens.ts. Edit public-document.ts. */\n@import './tokens.css';\n" +
      publicSurfaceCss,
  },
  {
    path: 'web/public/offline.html',
    parser: 'html',
    source: publicDocument({ ...offlineCopy, documentTitle: 'Нет подключения — iSign' }),
  },
];
for (const { path, source, parser } of outputs) {
  const options = await resolveConfig(path, { editorconfig: true });
  const expected = await format(source, { ...options, parser, filepath: path });
  if (process.argv.includes('--check')) {
    if ((await readFile(path, 'utf8')) !== expected)
      throw new Error(path + ' is stale. Run pnpm exec tsx backend/scripts/design-tokens.ts');
  } else await writeFile(path, expected);
}
if (process.argv.includes('--check'))
  console.log('Design tokens and public surfaces match their sources.');
